                    : "bg-ov-600 text-white"
                  : dunkel
                    ? "text-white/70 hover:text-white"
                    : "text-ink-600 hover:text-ink-900"
              )}
            >
              <span className="sr-only">{z.titel}: </span>
              {z.label}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}

