            <ul className="mt-5 space-y-2.5">
              {b.punkte.map((p) => (
                <li key={p} className="flex gap-3 text-[14px] leading-relaxed text-ink-700">
                  <span aria-hidden="true" className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-ov-500" />
                  {p}
                </li>
              ))}
            </ul>
          </Reveal>
        );
      })}
    </div>
  );
}

